<?php require __DIR__.'/../config/config.php';require __DIR__.'/../includes/functions.php';$id=$_GET['id']??'';$s=$pdo->prepare('SELECT * FROM buku WHERE id_buku=?');$s->execute([$id]);$book=$s->fetch();if(!$book){flash('warning','Buku tidak ditemukan.');redirect('index.php');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){$book=array_merge($book,$_POST);$book['id_buku']=$id;if($book['judul']==='')$errors[]='Judul wajib diisi.';if($book['pengarang']==='')$errors[]='Pengarang wajib diisi.';if($book['tahun_terbit']!==''&&!ctype_digit((string)$book['tahun_terbit']))$errors[]='Tahun terbit harus angka.';if(!ctype_digit((string)$book['stok']))$errors[]='Stok harus angka >= 0.';if(!$errors){$s=$pdo->prepare('UPDATE buku SET judul=?,pengarang=?,penerbit=?,tahun_terbit=?,stok=? WHERE id_buku=?');$s->execute([$book['judul'],$book['pengarang'],$book['penerbit']?:null,$book['tahun_terbit']?:null,$book['stok'],$id]);flash('success','Data buku diperbarui.');redirect('index.php');}}$title='Edit Buku';$edit=true;require __DIR__.'/../includes/header.php';?><h3 class="mb-3">Edit Buku</h3><?php require '_form.php';require __DIR__.'/../includes/footer.php';?>
